 "content": "def transform(grid):
    """Extend a solid color-2 rectangle outward in cardinal directions, stopping at nonzero markers."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return out
    r0, r1 = min(r for r, _ in cells), max(r for r, _ in cells)
    c0, c1 = min(c for _, c in cells), max(c for _, c in cells)
    # Project the rectangle's four sides along their rows/columns. Any existing
    # nonzero cell other than the rectangle is a blocker and remains unchanged.
    for r in range(r0, r1 + 1):
        for step in (-1, 1):
            c = c0 - 1 if step < 0 else c1 + 1
            while 0 <= c < w and grid[r][c] == 0:
                out[r][c] = 2
                c += step
    for c in range(c0, c1 + 1):
        for step in (-1, 1):
            r = r0 - 1 if step < 0 else r1 + 1
            while 0 <= r < h and grid[r][c] == 0:
                out[r][c] = 2
                r += step
    return out
